We shall consider the following information theoretic quantities. Let $A$ be a quantum register. Let $\varepsilon \geq 0$. 
\begin{enumerate}
\item {\bf Fidelity} For $\rho,\sigma \in \mathcal{D}(A)$, $$\F(\rho,\sigma)\ensuremath{ \stackrel{\mathrm{def}}{=} }\onenorm{\sqrt{\rho}\sqrt{\sigma}}.$$ For classical probability distributions $P = \{p_i\}, Q =\{q_i\}$, $$\F(P,Q)\ensuremath{ \stackrel{\mathrm{def}}{=} } \sum_i \sqrt{p_i \cdot q_i}.$$

\item {\bf Entropy} For $\rho\in\mathcal{D}(A)$, $$S(\rho_A) \ensuremath{ \stackrel{\mathrm{def}}{=} } - \ensuremath{ \mathrm{Tr} }(\rho_A\log\rho_A) .$$ 
\item {\bf Relative entropy} For $\rho,\sigma\in \mathcal{D}(A)$ such that $\text{supp}(\rho) \subset \text{supp}(\sigma)$, $$\relent{\rho}{\sigma} \ensuremath{ \stackrel{\mathrm{def}}{=} } \ensuremath{ \mathrm{Tr} }(\rho\log\rho) - \ensuremath{ \mathrm{Tr} }(\rho\log\sigma) .$$ 
\item {\bf Relative max-entropy} For $\rho,\sigma\in \mathcal{D}(A)$ such that $\text{supp}(\rho) \subset \text{supp}(\sigma)$, $$ \rminent{\rho}{\sigma}  \ensuremath{ \stackrel{\mathrm{def}}{=} }  \inf \{ \lambda \in \mathbb{R} : 2^{\lambda} \sigma \geq \rho \}  .$$
\item {\bf Mutual information} For $\rho_{AB}\in \mathcal{D}(AB)$, $$\mutinf{A}{B}_{\rho}\ensuremath{ \stackrel{\mathrm{def}}{=} } S(\rho_A) + S(\rho_B)-S(\rho_{AB}) = \relent{\rho_{AB}}{\rho_A\otimes\rho_B}.$$
\item {\bf Conditional mutual information} For $\rho_{ABC}\in\mathcal{D}(ABC)$, $$\condmutinf{A}{B}{C}_{\rho}\ensuremath{ \stackrel{\mathrm{def}}{=} } \mutinf{A}{BC}_{\rho}-\mutinf{A}{C}_{\rho}.$$
\end{enumerate}
\label{def:infquant}

Consider,
\begin{eqnarray*}
\condmutinf{A_1A_2\ldots A_k}{B}{C}_{\rho}&=&\condmutinf{A_1}{B}{C}_{\rho}+\condmutinf{A_2A_3\ldots A_k}{B}{A_1C}_\rho\\
&=&\condmutinf{A_1}{B}{C}_{\rho}+\mutinf{A_2A_3\ldots A_k}{A_1BC}_{\rho}-\mutinf{A_1}{A_2A_3\ldots A_k}\rho\\
&=&\condmutinf{A_1}{B}{C}_{\rho}+\mutinf{A_2A_3\ldots A_k}{A_1BC}_{\rho}\\
&\geq&\condmutinf{A_1}{B}{C}_{\rho}+\condmutinf{A_2A_3\ldots A_k}{B}{C}_{\rho}
\end{eqnarray*}
The first and second equalities follow from the definition of the conditional mutual information. The third equality is from the independence between $A_1$ and $A_2A_3\ldots A_k$. The last inequality is from strong subadditivity (Fact~\ref{fact:strongsubadditivity}). Proof follows by induction.

\label{thm:protocol}
\label{qbev}
Given quantum states $\rho,\sigma$ on a Hilbert space $\H$ with dimension $N$, such that $\text{supp}(\rho) \subset \text{supp}(\sigma)$. Alice is given the eigen-decomposition of $\rho$ and Bob is given the eigen-decomposition of $\sigma$. Let  $\relent{\rho}{\sigma}$ and $\ve >0$ be known to Alice and Bob. There exists an entanglement assisted quantum one-way communication protocol, with Alice sending $\O(\relent{\rho}{\sigma}+1)/\ve^4)$ bits of communication to Bob, such that the state $\tilde{\rho}$ that Bob outputs at the end of the protocol satisfies  $\F(\rho,\tilde{\rho})\geq 1-5\ve$ .

Let the eigen-decomposition of $\rho$ be $\sum_{i=1}^Na_i\ketbra{a_i}$ and that of $\sigma$ be $\sum_{i=1}^Nb_i\ketbra{b_i}$. Define $c\ensuremath{ \stackrel{\mathrm{def}}{=} }\relent{\rho}{\sigma}$, $\delta \ensuremath{ \stackrel{\mathrm{def}}{=} } (\ve/3)^4$ and $c' \ensuremath{ \stackrel{\mathrm{def}}{=} } (c+2)/\delta$. Without loss of generality, assume $a_1,a_2\ldots a_N, \frac{2^{c'}}{\delta}b_1,\frac{2^{c'}}{\delta}b_2\ldots \frac{2^{c'}}{\delta}b_N$ to be rational numbers, and define $K$ be the least common multiple of their denominators. The error due to this assumption can be made arbitrarily close to $0$, for large enough $K$.  

Let $\set{\ket{1},\ket{2}\ldots \ket{N}}$ be an orthonormal basis for $\H$. Introduce registers $A_1,B_1$ associated to $\H$ and registers $A_2,B_2$ associated to some Hilbert space $\H'$ with an orthonormal basis $\set{\ket{1},\ket{2}\ldots \ket{K}}$.

Consider the following state on $A_1,A_2,B_1,B_2$. 
\begin{equation}
\label{eq:sharedstate}
\ket{S}_{A_1A_2B_1B_2} \ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{1}{\sqrt{KN}}\sum_{i=1}^N \ket{i,i}_{A_1B_1} \otimes \left( \sum_{m=1}^{K}\ket{m, m}_{A_2B_2} \right)
\end{equation}

For brevity, define registers $A,B$ such that $A\ensuremath{ \stackrel{\mathrm{def}}{=} } A_1A_2$ and $B\ensuremath{ \stackrel{\mathrm{def}}{=} } B_1B_2$.

The protocol is described below.

\begin{mdframed}
\bigskip
\textbf{Input:} Alice is given $\rho=\sum_{i=1}^Na_i\ketbra{a_i}$. Bob is given $\sigma=\sum_{i=1}^Nb_i\ketbra{b_i}$.
\bigskip



\textbf{Shared resources:} Alice and Bob hold $\lceil N\log(\frac{1}{\delta}) \rceil$ registers $A_1^iA_2^iB_1^iB_2^i$ ($i \in [\lceil N\log(\frac{1}{\delta}) \rceil]$), such that $A_1^i\equiv A_1, A^i_2\equiv A_2, B_1^i\equiv B_1,B_2^i\equiv B_2$. The shared state in register $A_1^iA_2^iB_1^iB_2^i$ is $\ket{S}_{A_1^iA_2^iB_1^iB_2^i}$. Let $i$ refer to the `index' of corresponding registers.

They also share infinitely many random hash functions $h_1,h_2,\cdots$, where each $h_l:\set{0,\cdots,N-1}\rightarrow\set{0,1}$.

\begin{enumerate}

\item \textbf{For} $i=1$ to $\lceil N\log(\frac{1}{\delta}) \rceil$,

\begin{enumerate}

\item Alice performs the measurement $\set{P_A,I_A- P_A}$ on each register $A_1^iA^i_2$ where,
\begin{equation}
\label{eq:aliceproj}
P_A\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{a_i}_{A_1}\bra{a_i}_{A_1}\otimes\left(\sum_{m=1}^{Ka_i}\ket{m}_{A_2}\bra{m}_{A_2}\right) .
\end{equation}

On each index $i$, she declares \textit{success} if her outcome corresponds to $P_A$.

\item Bob performs the measurement $\set{P_B,I_B- P_B}$ on each register $B_1^iB^i_2$ where,
\begin{equation}
\label{eq:bobproj}
P_B\ensuremath{ \stackrel{\mathrm{def}}{=} } \sum_i\ket{b_i}_{B_1}\bra{b_i}_{B_1}\otimes\left(\sum_{m=1}^{\min\{\frac{K}{\delta} 2^{c'} b_i,K\}}\ket{m}_{B_2}\bra{m}_{B_2}\right) .
\end{equation}

On each index $i$, he declares \textit{success} if his outcome corresponds to $P_B$.
\end{enumerate}

\textbf{Endfor}

\item If Alice does not succeed on any index, she aborts.

\item Else, Alice selects the first index $m$ where she succeeds and sends to Bob the binary encoding of $k=\lceil m/N\rceil$ using $\lceil\log\log\frac{1}{\delta}\rceil$ bits.  

\item Alice sends $\{ h_l(m\mod N) |~ l \in  [\lceil r + 2\log\frac{1}{\delta}\rceil]\}$  to Bob.

\item  Define $S_B \ensuremath{ \stackrel{\mathrm{def}}{=} } \{ t |~ \text{ Bob succeeds on index } $t$\} \cap \{(k-1)N,  \cdots, k N -1\}$. If $S_B$ is empty, he outputs $\ketbra{0}$. Bob selects the first index $n$ in $S_B$ such that $\forall l \in  [\lceil r + 2\log\frac{1}{\delta}\rceil]: h_l(n \mod N) = h_l(m \mod N) $ and outputs the state in $B_1^n$ (if no such index exists, he outputs $\ketbra{0}$).  

\end{enumerate}

\end{mdframed}
\bigskip

We analyze the protocol through a series of claims. 
Following claim computes the probability of success for Alice and Bob.

\begin{claim}
\label{claim:successprob}
For each index $i$, $\prob{\text{Alice succeeds}}=\frac{1}{N}$; $\prob{\text{Bob succeeds}}\leq\frac{2^{c'}}{\delta N}$
\end{claim}

\begin{proof}
Follows from direct calculation.

Define $R_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } a_i \abs{\braket{a_i}{g_j}}^2$ and $R'_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } g_i \abs{\braket{a_i}{g_j}}^2$. Note that both $R \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R_{ij}\}$ and $R' \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R'_{ij}\}$ form probability distributions over $[N^2]$. Also note that $\F(R,R') = \ensuremath{ \mathrm{Tr} }(\sqrt{\rho}\sqrt{\rho'})$. Consider
\begin{align*}
 \abs{\braket{S_A(\rho)}{S_A(\rho')}} & =\sum_{i,j}\min(R_{ij},R'_{i,j}) = 1 - \frac{1}{2}\onenorm{R-R'} \nonumber\\
 & \geq 1 - \sqrt{1-\F(R,R')^2} = 1 - \sqrt{1-(\ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})^2} \nonumber \\
 & \geq 1 - \sqrt{2(1- \ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})} \geq  1- \sqrt{2 \sqrt{1-\F(\rho,\rho')^2}}  \nonumber \\
 & \geq 1- 2 (1-\F(\rho,\rho'))^{1/4} . \tag*{\qedhere} 
  \end{align*}
where the first equality is from the definitions of $\ket{S_A(\rho)}$ and $\ket{S_A(\rho')}$; the second equality is from the definition of $\ell_1$ distance; the first inequality is from ~\ref{fact:tracefidelityequi}; the second inequality is from the fact that $\ensuremath{ \mathrm{Tr} }\sqrt{\rho}\sqrt{\rho'}\leq 1$; the third inequality is from Facts~\ref{fact:fidelityvstrace}.

Consider,
\begin{equation*}
(I_A\otimes P_B)\ket{S_A(\rho')} = \frac{1}{\sqrt{K}}\sum_{i,j=1}^N\ket{\conjugate{g_j}} \ket{b_i}\braket{b_i}{g_j} \left(\sum_{m=1}^{\min\{\lceil Kg_j\rceil, \frac{K}{\delta} 2^{c'}b_i\}}\ket{m, m} \right).
\end{equation*}
Therefore,
\begin{align}
& \norm{(I_A\otimes P_B)\ket{S_A(\rho')} }^2 \geq \sum_{i,j=1}^N \abs{\braket{b_i}{g_j}}^2 \min\{g_j, \frac{1}{\delta}2^{c'}b_i \} \nonumber \\
& \geq \sum_{j=1}^N g_j \left(\sum_{i|~b_i\geq \delta 2^{-c'}g_j} \abs{\braket{b_i}{g_j}}^2 \right) \geq \sum_{j=1}^N g_j(1- \delta) = 1- \delta  . \quad \mbox{(using Claim~\ref{claim:1})} \label{eq:probonrho'}
\end{align}
Using the above,

\begin{align*}
& \prob{\text{Bob succeeds}|~\text{Alice succeeds}}  =  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho)} \\
& \geq  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  - \frac{1}{2} \onenorm{S_A(\rho) - S_A(\rho')} \\
& = \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  -  \sqrt{1- \abs{\braket{S_A(\rho)}{S_A(\rho')}}^2} \quad \mbox{(Fact~\ref{fact:tracefidelityequi})} \\
& \geq  1 -  \delta  - 2  \sqrt{ (1-\F(\rho,\rho'))^{1/2}}  . \quad \mbox{(Claim~\ref{claim:2} and Eq.~\eqref{eq:probonrho'})}
\end{align*}

\label{def:badevent}
\begin{itemize}

\item $T_1$ is the event that Alice does not succeed on any of the indices.

\item $T_2$ is the event that $m \notin S_B$ conditioned on $\neg T_1$ .
\item $T_3$ represents the event that $n \neq m$ conditioned on $\neg T_1$.
\end{itemize}

\begin{enumerate}

\item $\prob{T_1}\leq\br{1-\frac{1}{N}}^{\lceil N \cdot \log\frac{1}{\ve}\rceil}\leq \exp^{-\lceil\log\frac{1}{\ve}\rceil}\leq  \delta$.

\item Follows from Claim \ref{claim:relativeprob}.

\item For this argument we condition on $\neg T_1$ for all events below. From Claim \ref{claim:successprob} and the fact that Bob independently measures each index, we have  $\expec{}{\abs{S_B}}= N\cdot \prob{\text{Bob succeeds}} \leq \frac{2^{c'}}{\delta}$. Using Markov's inequality, 
\begin{equation} \label{eq:sb} 
\prob{\abs{S_B} \geq \frac{2^{c'}}{\delta\ve}}\leq \frac{\delta\ve}{2^{c'}} \cdot \expec{}{\abs{S_B}} \leq \ve . 
\end{equation}

    Thus
    \begin{align*}
    \prob{T_3} & \leq\prob{\abs{S_B}\geq \frac{2^{c'}}{\delta\ve} \text{ or } m \notin S_B} +  \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta\ve}} \\ & \leq \prob{\abs{S_B}\geq \frac{2^{c'}}{\delta\ve}} + \prob{T_2} + \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta\ve}} \\
     & \leq 2 \ve+\prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta\ve}}  \quad \mbox{(Eq.~\eqref{eq:sb} and item 2. of this claim)}\\
     & \leq 2\ve + 2^{- \lceil c' + \log\frac{1}{\delta}+ 2\log\frac{1}{\ve}\rceil} \cdot \frac{2^{c'}}{\delta\ve} \quad  \leq \quad 3 \ve.
    \end{align*}

\end{enumerate}

\label{thm:directsumoneway}
Let $\X,\Y,\Z$ be finite sets, $f\subseteq\X\times\Y\times\Z$ be a relation, $0<\ve,\delta$ be error parameters and $k>1$ be an integer. We have
\[\dqcc{}{\ve}{f^k}\geq \Omega \br{k \br{\delta^9\cdot\dqcc{}{\ve+\delta}{f}-1}}.\]

\label{thm:correlatedsampling}
Let $\rho,\sigma$ be quantum states on a Hilbert space $\H$ of dimension $N$. Alice is given the eigen-decomposition of $\rho$ and Bob is given the eigen-decomposition of $\sigma$.  There exists a zero-communication  protocol satisfying the following.
\begin{enumerate}
\item Alice outputs registers  $A_1,A_2$ and and Bob outputs registers $B_1,B_2$ respectively, such that state in $A_1$ is $\rho$, the state in $B_1$ is $\sigma$ and $A_1\equiv B_1, A_2\equiv B_2$.
\item Let $M = \{M_1,M_2\ldots M_w\}$ be a projective measurement, in the support of $A_1A_2$. Let $M$ be performed by Alice on the joint system $A_1A_2$ with outcome $I \in [w]$ and by Bob on the joint system $B_1B_2$ with outcome $J \in [w]$. Then $\Pr[I = J] \geq \left(1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}\right)^{3}$. 
\end{enumerate}

Let eigen-decomposition of $\rho$ be $\sum_{i=1}^Na_i\ketbra{a_i}$ and of $\sigma$ be $\sum_{i=1}^Nb_i\ketbra{b_i}$. Let $\set{\ket{1},\ket{2}\ldots \ket{N}}$ be an orthonormal basis for $\H$. We assume that $a_1, \ldots, a_N, b_1,  \ldots b_N$ are rational numbers and let $K$ be the least common multiple of their denominators. The error due to this assumption goes to $0$ as $K \rightarrow \infty$. 

Introduce registers $A_1,B_1$ associated to $\H$ and registers $A_2,B_2$ associated to some Hilbert space $\H'$ with an orthonormal basis $\set{\ket{1},\ket{2}\ldots \ket{K}}$.

Consider the following state shared in $A_1,A_2,B_1,B_2$.
\begin{equation*}
\ket{S}_{A_1B_1A_2B_2} \ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{1}{\sqrt{KN}}\sum_{i=1}^N \ket{i,i}_{A_1B_1} \otimes \left(\sum_{m=1}^{K}\ket{m, m}_{A_2B_2} \right)
\end{equation*}

 For brevity, define the registers $A\ensuremath{ \stackrel{\mathrm{def}}{=} } A_1A_2$ and $B \ensuremath{ \stackrel{\mathrm{def}}{=} } B_1B_2$. The protocol is described below.
\begin{mdframed}
\bigskip
\textbf{Input:} Alice is given $\rho=\sum_{i=1}^Na_i\ketbra{a_i}$. Bob is given $\sigma=\sum_{i=1}^Nb_i\ketbra{b_i}$.
\bigskip

\textbf{Shared resources:} Alice and Bob hold infinitely many registers $A_1^iA_2^iB_1^iB_2^i$ ($i>0$), such that $A_1^i\equiv A_1, A^i_2\equiv A_2, B_1^i\equiv B_1,B_2^i\equiv B_2$. The shared state in register $A_1^iA_2^iB_1^iB_2^i$ is $\ket{S}_{A_1^iA_2^iB_1^iB_2^i}$. Let $A \equiv A_1A_2$ and $B\equiv B_1B_2$ be used as output registers. Let $i$ refer to the `index' of corresponding registers.

\begin{enumerate}

\item For each $i>0$, Alice performs the measurement $\set{P_A,I- P_A}$ on the registers $A^i_1A^i_2$, where
\begin{equation*}
P_A\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{a_i}_{A_1}\bra{a_i}_{A_1}\otimes \left(\sum_{m=1}^{Ka_i}\ket{m}_{A_2}\bra{m}_{A_2}\right)
\end{equation*}

She declares \textit{success} if she obtains outcome corresponding to $P_A$. She stops once she succeeds in some register $A^j$, and swaps $A^j$ with $A$. 

\item For each $i>0$, Bob performs the measurement $\set{P_B,I- P_B}$ on the registers $B^i_1B^i_2$, where
\begin{equation*}
P_B\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{b_i}_{B_1}\bra{b_i}_{B_1}\otimes \left(\sum_{m=1}^{Kb_i}\ket{m}_{B_2}\bra{m}_{B_2}\right)
\end{equation*}

He declares \textit{success} if he obtains outcome corresponding to $P_B$. He stops once he succeeds in some register $B^j$, and swaps $B^j$ with $B$.

\end{enumerate}

\end{mdframed}
\bigskip

At the end of above protocol, let the joint state in the register $AB$ be $\tau$. The following claim shows the first part of the theorem. 
\begin{claim}\label{redstate}
$\ensuremath{ \mathrm{Tr} }_{A_2B_1B_2}(\tau)=\rho$ and $\ensuremath{ \mathrm{Tr} }_{A_1A_2B_2}(\tau)=\sigma$.
\end{claim}
\begin{proof}
It is easily seen that the marginal of the state $(P_A \otimes I_B) \ket{S}$ in register $A$  is $\rho$. Similarly the marginal of the state $(I_A \otimes P_B) \ket{S}$ in register $B$ in  is $\sigma$.

Similarly, consider a projection $P_{BB_1}$ as defined below (for an appropriately chosen $\delta$) and $I_{BB_1}$ the identity operator on register $BB_1$. Bob performs a measurement $\{P_{BB_1},I_{BB_1}-P_{BB_1}\}$  on registers $BB_1$ on each copy of $\ket{\psi}$ and \textit{accepts} the index of a copy iff the outcome of measurement corresponds to $P_{BB_1}$ (which we refer to as a success for Bob).
\begin{equation*}
P_{BB_1}=\sum_{i=1}^N\ket{b_i}_B\bra{b_i}_B\otimes \left(\sum_{m=1}^{\text{min}\{\lceil 2^{c}K b_i/\delta\rceil, K\}}\ket{m}_{B_1}\bra{m}_{B_1}\right) .
\end{equation*}
Again it is easily argued that (in the limit $K \rightarrow \infty$) the marginal state in $B$ (and also in $A$), in the first copy of $\ket{\psi}$ on which Alice succeeds, is $\rho$.  Using crucially the fact that $\rho \leq 2^c \sigma$, we argue that after Alice's measurement succeeds in a copy, Bob's measurement also succeeds with high probability. Hence, by {\em gentle measurement lemma} (\cite{Winter:1999,Ogawa:2002}), the marginal state in register $B$ is not disturbed much, conditioned on success of both Alice and Bob.  We also argue that Alice can communicate the index of this copy to Bob with communication of $\O(c)$ bits (for constant $\ve$).

