	\label{fact:monotonequantumoperation}
For states $\rho$, $\sigma \in \mathcal{D}(A)$, and quantum operation $\E(\cdot):\mathcal{L}(A)\rightarrow \mathcal{L}(B)$, it holds that
\begin{align*}
	\onenorm{\E(\rho) - \E(\sigma)} \leq \onenorm{\rho - \sigma} \quad \mbox{and} \quad \F(\E(\rho),\E(\sigma)) \geq \F(\rho,\sigma) \quad \mbox{and} \quad \relent{\rho}{\sigma}\geq \relent{\E(\rho)}{\E(\sigma)}.
\end{align*}
In particular, for bipartite states $\rho^{AB},\sigma^{AB}\in \mathcal{D}(AB)$, it holds that
\begin{align*}
	\onenorm{\rho^{AB} - \sigma^{AB}} \geq \onenorm{\rho^A - \sigma^A} \quad \mbox{and} \quad \F(\rho^{AB},\sigma^{AB}) \leq \F(\rho^A,\sigma^A) \quad \mbox{and} \quad \relent{\rho_{AB}}{\sigma_{AB}}\geq \relent{\rho_A}{\sigma_A} .
\end{align*}

\label{fact:onenorm vs twonorm}
Let $A, B$ be two positive semidefinite operators on Hilbert space $\H$. Then
\[\onenorm{A-B}\geq\norm{\sqrt{A}-\sqrt{B}}^2_2.\]

\label{fact:substrate}
Given $\rho, \sigma \in \mathcal{D}(A)$, such that $\text{supp}(\rho) \subset \text{supp}(\sigma)$. For any $\ve>0$, there exists $\rho'\in \mathcal{D}(A)$ such that
\[\F(\rho,\rho')\geq1-\ve\quad \mbox{and}\quad \rminent{\rho'}{\sigma}\leq\frac{\relent{\rho}{\sigma}+1}{\ve}+\log\frac{1}{1-\ve}.\]

\label{fact:gentlemeasurement}
Let $\rho\in \mathcal{D}(A)$  and $\Pi$ be a projector. Then,
\[\F(\rho,\frac{\Pi \rho \Pi}{\ensuremath{ \mathrm{Tr} } \Pi \rho })\geq \sqrt{\ensuremath{ \mathrm{Tr} } \Pi \rho}.\]

\label{fact:ruskai}
Given quantum states $\sigma_{AB}\in \mathcal{D}(AB), \rho_A\in \mathcal{D}(A)$, such that $\text{supp}(\rho_A)\subset\text{supp}(\sigma_A)$, it holds that 
$$\ensuremath{ \mathrm{Tr} }(e^{\text{log}(\sigma_{AB})-\text{log}(\sigma_{A}\otimes I_B)+\text{log}(\rho_{A}\otimes I_B)})<1.$$

\label{fact:conditionalmutinf}
For a quantum state $\rho_{AB}\in\mathcal{D}(AB)$, it holds that $\abs{\mathrm{S}(\rho_A)-\mathrm{S}(\rho_B)}\leq\mathrm{S}(\rho_{AB})\leq\mathrm{S}(\rho_A)+\mathrm{S}(\rho_B)$. Furthermore,
\[\mutinf{A}{B}_{\rho}=\mathrm{S}(\rho_A)+\mathrm{S}(\rho_B)-\mathrm{S}(\rho_{AB})\leq 2\mathrm{S}(\rho_A).\]

\label{fact:chainrulemutualinf}
Let $\rho_{A_1A_2\ldots A_kBC} \in \mathcal{D}(A_1\cdots A_k BC)$ such that $\rho_{A_1A_2\ldots A_k}=\rho_{A_1}\otimes\rho_{A_2}\otimes\ldots\rho_{A_k}$. Then,
\[\condmutinf{A_1A_2\ldots A_k}{B}{C}_{\rho}\geq\sum_{i=1}^k\condmutinf{A_i}{B}{C}_{\rho}.\]

\label{fact:relative entropy splitting}
